import { ethers } from 'ethers';
import { 
    MULTICALL3_ADDRESS, 
    MULTICALL3_ABI, 
    ERC20_ABI, 
    STAKE_ABI, 
    BOND_ABI, 
    TURBINE_ABI, 
    SPIDER_WEB_ABI,
    TOTAL_STAKE_MULTICALL_ABI,
    MINT_STAKE_CONTRACTS,
    BOND_CONTRACTS,
    TURBINE_CONTRACT,
    SPIDER_WEB_CONTRACT,
    TOTAL_STAKING_QUERY_CONTRACT,
    TOKEN_LGNS,
    TOKEN_SLGNS
} from '../constants.ts';
import { AddressEntry, StakingData } from '../types.ts';

export class BlockchainService {
    private provider: ethers.JsonRpcProvider;
    private multicallContract: ethers.Contract;

    constructor(rpcUrl: string) {
        this.provider = new ethers.JsonRpcProvider(rpcUrl);
        this.multicallContract = new ethers.Contract(MULTICALL3_ADDRESS, MULTICALL3_ABI, this.provider);
    }

    private encodeCall(contractInterface: ethers.Interface, fnName: string, args: any[]): string {
        return contractInterface.encodeFunctionData(fnName, args);
    }

    private decodeResult(contractInterface: ethers.Interface, fnName: string, data: string): any {
        try {
            if (!data || data === '0x') return null;
            return contractInterface.decodeFunctionResult(fnName, data);
        } catch (e) {
            return null;
        }
    }

    private parseTotalStakingFromRawData(rawData: string, userAddress: string = ''): bigint {
        try {
            if (!rawData || rawData === '0x' || rawData.length < 10) return 0n;

            const multicallInterface = new ethers.Interface(TOTAL_STAKE_MULTICALL_ABI);

            try {
                const decoded = multicallInterface.decodeFunctionResult('multiCall', rawData);
                const results = decoded[1];   

                for (let i = 0; i < results.length; i++) {
                    const res = results[i];
                    if (res && res !== '0x' && res.length >= 66) {
                        const val = BigInt(ethers.dataSlice(res, 0, 32));
                        if (val > 100n) return val; 
                    }
                }
            } catch (decodeError) {
                // Secondary parsing: try to find any 32-byte chunk that looks like a balance
                const hexStr = rawData.replace('0x', '');
                for (let i = 0; i <= hexStr.length - 64; i += 64) {
                    const chunk = '0x' + hexStr.substring(i, i + 64);
                    const val = BigInt(chunk);
                    if (val > 1000000n && val < 1000000000000000000000000n) return val;
                }
            }
        } catch (error) {
            console.error(`Parse total staking error for ${userAddress}:`, error);
        }
        return 0n;
    }

    private async queryTotalStaking(address: string): Promise<bigint> {
        try {
            const cleanAddr = address.toLowerCase().replace('0x', '');
            if (cleanAddr.length !== 40) return 0n;

            const prefix = "";
            const suffix = "00000000000000000000000000000000000000000000000000000000";

            const callData = ("0x" + prefix + cleanAddr + suffix);

            // Using a plain eth_call to avoid high-level ethers.js validation that causes "missing revert data"
            const result = await this.provider.send('eth_call', [{
                to: TOTAL_STAKING_QUERY_CONTRACT,
                data: callData
            }, 'latest']).catch(() => '0x');

            if (result && result !== '0x') {
                return this.parseTotalStakingFromRawData(result, address);
            }
            return 0n;
        } catch (e: any) {
            console.warn(`[BlockchainService] Silent fail for totalStaking at ${address}:`, e.message);
            return 0n;
        }
    }

    async batchQuery(addresses: AddressEntry[], batchSize: number = 10): Promise<Map<string, StakingData>> {
        const resultsMap = new Map<string, StakingData>();
        const erc20Int = new ethers.Interface(ERC20_ABI);
        const stakeInt = new ethers.Interface(STAKE_ABI);
        const bondInt = new ethers.Interface(BOND_ABI);
        const turbineInt = new ethers.Interface(TURBINE_ABI);
        const spiderInt = new ethers.Interface(SPIDER_WEB_ABI);

        for (let i = 0; i < addresses.length; i += batchSize) {
            const chunk = addresses.slice(i, i + batchSize);
            const firstPassCalls: any[] = [];

            chunk.forEach(addr => {
                firstPassCalls.push({ target: TURBINE_CONTRACT, allowFailure: true, callData: this.encodeCall(turbineInt, 'getTurbineBal', [addr.aAddress]) });
                firstPassCalls.push({ target: SPIDER_WEB_CONTRACT, allowFailure: true, callData: this.encodeCall(spiderInt, 'claimable', [addr.aAddress]) });
                firstPassCalls.push({ target: TOKEN_LGNS.address, allowFailure: true, callData: this.encodeCall(erc20Int, 'balanceOf', [addr.derivedAddress]) });
                firstPassCalls.push({ target: TOKEN_SLGNS.address, allowFailure: true, callData: this.encodeCall(erc20Int, 'balanceOf', [addr.derivedAddress]) });

                MINT_STAKE_CONTRACTS.forEach(c => firstPassCalls.push({ target: c, allowFailure: true, callData: this.encodeCall(stakeInt, 'getUserStakesCount', [addr.aAddress]) }));
                BOND_CONTRACTS.forEach(c => firstPassCalls.push({ target: c, allowFailure: true, callData: this.encodeCall(bondInt, 'getBondInfoDataLength', [addr.aAddress]) }));
            });

            const firstPassResponse = await this.multicallContract.aggregate3(firstPassCalls);
            let callIdx = 0;

            for (const addr of chunk) {
                const turbineBal = (firstPassResponse[callIdx++]?.success) ? (this.decodeResult(turbineInt, 'getTurbineBal', firstPassResponse[callIdx-1].returnData)?.[0] || 0n) : 0n;
                const spiderReward = (firstPassResponse[callIdx++]?.success) ? (this.decodeResult(spiderInt, 'claimable', firstPassResponse[callIdx-1].returnData)?.[0] || 0n) : 0n;
                const lgnsBal = (firstPassResponse[callIdx++]?.success) ? (this.decodeResult(erc20Int, 'balanceOf', firstPassResponse[callIdx-1].returnData)?.[0] || 0n) : 0n;
                const slgnsBal = (firstPassResponse[callIdx++]?.success) ? (this.decodeResult(erc20Int, 'balanceOf', firstPassResponse[callIdx-1].returnData)?.[0] || 0n) : 0n;

                const mintCounts = MINT_STAKE_CONTRACTS.map(() => (firstPassResponse[callIdx++]?.success) ? Number(this.decodeResult(stakeInt, 'getUserStakesCount', firstPassResponse[callIdx-1].returnData)?.[0] || 0) : 0);
                const bondCounts = BOND_CONTRACTS.map(() => (firstPassResponse[callIdx++]?.success) ? Number(this.decodeResult(bondInt, 'getBondInfoDataLength', firstPassResponse[callIdx-1].returnData)?.[0] || 0) : 0);

                const detailCalls: any[] = [];
                MINT_STAKE_CONTRACTS.forEach((c, ci) => { 
                    for(let j=0; j < mintCounts[ci]; j++) {
                        detailCalls.push({ target: c, allowFailure: true, callData: this.encodeCall(stakeInt, 'stakes', [addr.aAddress, j]) });
                    }
                });
                BOND_CONTRACTS.forEach((c, ci) => { 
                    for(let j=0; j < bondCounts[ci]; j++) {
                        detailCalls.push({ target: c, allowFailure: true, callData: this.encodeCall(bondInt, 'bondInfoData', [addr.aAddress, j]) });
                    }
                });

                let mintTotal = 0n, bondTotal = 0n;
                if (detailCalls.length > 0) {
                    const detailRes = await this.multicallContract.aggregate3(detailCalls);
                    let di = 0;
                    mintCounts.forEach(count => { 
                        for(let j=0; j < count; j++) {
                            const res = detailRes[di++];
                            if(res?.success) mintTotal += BigInt(this.decodeResult(stakeInt, 'stakes', res.returnData)?.principal || 0n);
                        }
                    });
                    bondCounts.forEach(count => { 
                        for(let j=0; j < count; j++) {
                            const res = detailRes[di++];
                            if(res?.success) bondTotal += BigInt(this.decodeResult(bondInt, 'bondInfoData', res.returnData)?.payout || 0n);
                        }
                    });
                }

                const totalStakingValue = await this.queryTotalStaking(addr.aAddress);

                resultsMap.set(addr.aAddress, {
                    totalStaking: ethers.formatUnits(totalStakingValue, 9),
                    mintStaking: ethers.formatUnits(mintTotal, 9),
                    bondStaking: ethers.formatUnits(bondTotal, 9),
                    spiderWebReward: ethers.formatUnits(spiderReward, 9),
                    turbineBalance: ethers.formatUnits(turbineBal, 9),
                    derivedLgns: ethers.formatUnits(lgnsBal, TOKEN_LGNS.decimals),
                    derivedSlgns: ethers.formatUnits(slgnsBal, TOKEN_SLGNS.decimals),
                    lastUpdated: Date.now()
                });
            }
        }
        return resultsMap;
    }
}

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { 
    Search, 
    RefreshCcw, 
    Download, 
    Upload, 
    Edit2, 
    Save, 
    X, 
    Database, 
    Activity, 
    Wallet,
    Info,
    ListFilter,
    ArrowUpRight,
    TrendingUp,
    Coins,
    Layers,
    Copy,
    Check,
    Settings,
    FileJson,
    PieChart,
    ChevronDown,
    Zap
} from 'lucide-react';
import { AddressEntry, StakingData } from './types.ts';
import { DEFAULT_RPC } from './constants.ts';
import { BlockchainService } from './services/blockchainService.ts';

const INITIAL_ADDRESSES: AddressEntry[] = [
    {
      aAddress: "0x80cB03984E41CBdaE772D7090f66fa699A3CDF3F",
      log: "5月20号",
      remark: "Demo Account",
      derivedAddress: "0x309ca717d6989676194b88fd06029a88ceefee60",
      split: "5-5开"
    }
];

export default function App() {
    const [addresses, setAddresses] = useState<AddressEntry[]>([]);
    const [stakingData, setStakingData] = useState<Record<string, StakingData>>({});
    const [rpcUrl, setRpcUrl] = useState(DEFAULT_RPC);
    const [batchSize, setBatchSize] = useState(10);
    const [searchTerm, setSearchTerm] = useState('');
    const [loading, setLoading] = useState(false);
    const [editingRemark, setEditingRemark] = useState<{ address: string, value: string } | null>(null);
    const [copiedAddress, setCopiedAddress] = useState<string | null>(null);

    useEffect(() => {
        const saved = localStorage.getItem('polygon_addresses');
        if (saved) {
            setAddresses(JSON.parse(saved));
        } else {
            setAddresses(INITIAL_ADDRESSES);
        }

        const savedStats = localStorage.getItem('polygon_staking_stats');
        if (savedStats) {
            setStakingData(JSON.parse(savedStats));
        }
    }, []);

    const saveAddresses = (newAddresses: AddressEntry[]) => {
        const uniqueMap = new Map();
        newAddresses.forEach(item => {
            if (item.aAddress) {
                const key = item.aAddress.toLowerCase().trim();
                if (!uniqueMap.has(key)) {
                    uniqueMap.set(key, item);
                }
            }
        });
        const finalAddresses = Array.from(uniqueMap.values());
        setAddresses(finalAddresses);
        localStorage.setItem('polygon_addresses', JSON.stringify(finalAddresses));
    };

    const handleUpdateRemark = (address: string, newValue: string) => {
        const updated = addresses.map(item => 
            item.aAddress.toLowerCase() === address.toLowerCase() ? { ...item, remark: newValue } : item
        );
        saveAddresses(updated);
        setEditingRemark(null);
    };

    const handleRefresh = async () => {
        if (addresses.length === 0) return;
        setLoading(true);
        try {
            const service = new BlockchainService(rpcUrl);
            const results = await service.batchQuery(addresses, batchSize);
            const newStakingData = Object.fromEntries(results);
            setStakingData(prev => ({ ...prev, ...newStakingData }));
            localStorage.setItem('polygon_staking_stats', JSON.stringify({ ...stakingData, ...newStakingData }));
        } catch (error: any) {
            console.error("Refresh error:", error);
            // Better error reporting that doesn't block the UI
            const msg = error.message?.includes('missing revert data') 
                ? "RPC execution error. Some assets might be empty. Try a different RPC."
                : `Error: ${error.message}`;
            alert(msg);
        } finally {
            setLoading(false);
        }
    };

    const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = (event) => {
            try {
                const json = JSON.parse(event.target?.result as string);
                let importedItems: AddressEntry[] = [];
                if (Array.isArray(json)) {
                    importedItems = json;
                } else if (json.items && Array.isArray(json.items)) {
                    importedItems = json.items;
                }

                if (importedItems.length > 0) {
                    saveAddresses(importedItems);
                }
            } catch (err) {
                alert("Invalid JSON data.");
            }
        };
        reader.readAsText(file);
    };

    const handleExport = () => {
        const exportData = {
            generatedAt: new Date().toISOString(),
            total: addresses.length,
            items: addresses
        };
        const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(exportData, null, 2));
        const downloadAnchor = document.createElement('a');
        downloadAnchor.setAttribute("href", dataStr);
        downloadAnchor.setAttribute("download", `polygon_portfolio_export.json`);
        downloadAnchor.click();
    };

    const copyToClipboard = (text: string) => {
        navigator.clipboard.writeText(text);
        setCopiedAddress(text);
        setTimeout(() => setCopiedAddress(null), 2000);
    };

    const filteredAddresses = useMemo(() => {
        return addresses.filter(a => 
            (a.remark || "").toLowerCase().includes(searchTerm.toLowerCase()) || 
            (a.aAddress || "").toLowerCase().includes(searchTerm.toLowerCase())
        );
    }, [addresses, searchTerm]);

    const globalStats = useMemo(() => {
        let totals = { val: 0, turb: 0, spid: 0, mint: 0, bond: 0, dlgns: 0, dslgns: 0 };
        filteredAddresses.forEach(addr => {
            const data = stakingData[addr.aAddress];
            if (data) {
                totals.val += parseFloat(data.totalStaking) || 0;
                totals.turb += parseFloat(data.turbineBalance) || 0;
                totals.spid += parseFloat(data.spiderWebReward) || 0;
                totals.mint += parseFloat(data.mintStaking) || 0;
                totals.bond += parseFloat(data.bondStaking) || 0;
                totals.dlgns += parseFloat(data.derivedLgns) || 0;
                totals.dslgns += parseFloat(data.derivedSlgns) || 0;
            }
        });
        return totals;
    }, [stakingData, filteredAddresses]);

    const chartData = useMemo(() => {
        const total = globalStats.mint + globalStats.bond + globalStats.turb + globalStats.spid;
        if (total === 0) return [];
        return [
            { label: 'Minting', value: globalStats.mint, color: '#6366f1' },
            { label: 'Bonds', value: globalStats.bond, color: '#a855f7' },
            { label: 'Turbine', value: globalStats.turb, color: '#10b981' },
            { label: 'Spider', value: globalStats.spid, color: '#f59e0b' }
        ];
    }, [globalStats]);

    return (
        <div className="max-w-[1720px] mx-auto px-6 py-8 pb-20">
            {/* Header Area */}
            <header className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-8 mb-12">
                <div className="flex items-center gap-5">
                    <div className="relative">
                        <div className="absolute inset-0 bg-indigo-500 blur-2xl opacity-20 animate-pulse"></div>
                        <div className="relative bg-gradient-to-br from-indigo-500 to-indigo-700 p-4 rounded-3xl shadow-2xl">
                            <Zap className="text-white w-10 h-10" />
                        </div>
                    </div>
                    <div>
                        <h1 className="text-5xl font-black text-white tracking-tighter flex items-center gap-3">
                            Polygon <span className="text-indigo-500">Viz</span>
                        </h1>
                        <p className="text-slate-400 font-bold text-lg tracking-tight">Enterprise Multi-Wallet Analytics Dashboard</p>
                    </div>
                </div>

                <div className="flex flex-wrap items-center gap-4 w-full xl:w-auto">
                    <div className="flex items-center gap-3 bg-slate-800/60 backdrop-blur-xl p-3 rounded-2xl border border-white/5 shadow-xl">
                        <Settings className="w-5 h-5 text-slate-500" />
                        <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Concurrency:</span>
                        <select 
                            value={batchSize}
                            onChange={(e) => setBatchSize(Number(e.target.value))}
                            className="bg-slate-900/50 text-indigo-400 text-sm font-black px-4 py-1.5 rounded-xl border border-white/5 outline-none hover:bg-slate-900 transition-colors"
                        >
                            <option value={5}>LITE (5)</option>
                            <option value={10}>NORMAL (10)</option>
                            <option value={20}>TURBO (20)</option>
                        </select>
                    </div>
                    <div className="relative flex-1 xl:flex-none">
                        <input 
                            type="text" 
                            value={rpcUrl}
                            onChange={(e) => setRpcUrl(e.target.value)}
                            className="bg-slate-800/60 border border-white/5 text-slate-200 rounded-2xl px-5 py-4 text-sm w-full xl:w-[420px] outline-none shadow-2xl focus:border-indigo-500/50 transition-all font-mono"
                            placeholder="RPC Endpoint URL"
                        />
                    </div>
                    <button 
                        onClick={handleRefresh}
                        disabled={loading || addresses.length === 0}
                        className={`flex items-center justify-center gap-3 px-10 py-4 rounded-2xl font-black text-base transition-all shadow-[0_20px_50px_rgba(79,70,229,0.3)] ${
                            loading ? 'bg-slate-700 text-slate-400' : 'bg-indigo-600 hover:bg-indigo-500 text-white hover:-translate-y-1 active:translate-y-0'
                        }`}
                    >
                        <RefreshCcw className={`w-6 h-6 ${loading ? 'animate-spin' : ''}`} />
                        {loading ? 'SYNCHRONIZING...' : 'FETCH DATA'}
                    </button>
                </div>
            </header>

            {/* Visualization & Summary Section */}
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 mb-12">
                {/* Global Stats Matrix */}
                <div className="lg:col-span-8 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                    <SummaryTile icon={<Activity />} label="Aggregated Staking" value={globalStats.val} subValue="9 decimals" color="indigo" />
                    <SummaryTile icon={<TrendingUp />} label="Mint Pool" value={globalStats.mint} subValue="Principal" color="blue" />
                    <SummaryTile icon={<ArrowUpRight />} label="Active Bonds" value={globalStats.bond} subValue="Payouts" color="purple" />
                    <SummaryTile icon={<Wallet />} label="Turbine Liquid" value={globalStats.turb} subValue="Claimable" color="emerald" />
                    <SummaryTile icon={<Info />} label="Spider Web" value={globalStats.spid} subValue="Rewards" color="amber" />
                    <SummaryTile icon={<Coins />} label="LGNS Holding" value={globalStats.dlgns} subValue="Governance" color="pink" />
                    <SummaryTile icon={<Layers />} label="slgns Assets" value={globalStats.dslgns} subValue="Liquid Staking" color="cyan" />
                    <div className="bg-gradient-to-br from-indigo-600/20 to-purple-600/20 border border-indigo-500/20 rounded-3xl p-6 flex flex-col justify-center items-center text-center">
                        <span className="text-xs font-black text-indigo-400 uppercase tracking-widest mb-1">Total Assets</span>
                        <div className="text-3xl font-black text-white">{(globalStats.val + globalStats.dlgns + globalStats.dslgns).toLocaleString(undefined, { maximumFractionDigits: 2 })}</div>
                        <span className="text-[10px] text-slate-500 font-bold mt-2">REAL-TIME AGGREGATE</span>
                    </div>
                </div>

                {/* Donut Chart Visualization */}
                <div className="lg:col-span-4 bg-slate-800/40 border border-white/5 rounded-[2.5rem] p-8 flex flex-col items-center justify-center relative overflow-hidden group">
                    <div className="absolute top-6 left-8 flex items-center gap-2">
                        <PieChart className="w-5 h-5 text-indigo-500" />
                        <span className="text-xs font-black text-slate-400 uppercase tracking-widest">Asset Allocation</span>
                    </div>

                    {chartData.length > 0 ? (
                        <div className="flex flex-col items-center gap-8 w-full">
                            <div className="relative w-48 h-48">
                                <svg viewBox="0 0 100 100" className="w-full h-full transform -rotate-90">
                                    {(() => {
                                        let cumulativePercent = 0;
                                        const total = chartData.reduce((acc, d) => acc + d.value, 0);
                                        return chartData.map((slice, i) => {
                                            const percent = (slice.value / total) * 100;
                                            const startX = Math.cos(2 * Math.PI * cumulativePercent / 100);
                                            const startY = Math.sin(2 * Math.PI * cumulativePercent / 100);
                                            cumulativePercent += percent;
                                            const endX = Math.cos(2 * Math.PI * cumulativePercent / 100);
                                            const endY = Math.sin(2 * Math.PI * cumulativePercent / 100);
                                            const largeArcFlag = percent > 50 ? 1 : 0;
                                            const pathData = `M 50 50 L ${50 + 40 * startX} ${50 + 40 * startY} A 40 40 0 ${largeArcFlag} 1 ${50 + 40 * endX} ${50 + 40 * endY} Z`;
                                            return <path key={i} d={pathData} fill={slice.color} className="opacity-80 hover:opacity-100 transition-opacity cursor-pointer" />;
                                        });
                                    })()}
                                    <circle cx="50" cy="50" r="28" fill="#1e293b" />
                                </svg>
                                <div className="absolute inset-0 flex flex-col items-center justify-center text-center">
                                    <span className="text-[10px] font-black text-slate-500 uppercase">Yield</span>
                                    <span className="text-2xl font-black text-white">{( (globalStats.turb + globalStats.spid) / (globalStats.val || 1) * 100).toFixed(1)}%</span>
                                </div>
                            </div>
                            <div className="grid grid-cols-2 gap-4 w-full px-4">
                                {chartData.map((slice, i) => (
                                    <div key={i} className="flex items-center gap-2">
                                        <div className="w-3 h-3 rounded-full" style={{ backgroundColor: slice.color }}></div>
                                        <div className="flex flex-col">
                                            <span className="text-[10px] font-black text-slate-500 uppercase tracking-tighter leading-none">{slice.label}</span>
                                            <span className="text-xs font-black text-white">{((slice.value / (chartData.reduce((a,b)=>a+b.value,0)) || 1) * 100).toFixed(1)}%</span>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    ) : (
                        <div className="text-center py-20">
                            <Database className="w-12 h-12 text-slate-700 mx-auto mb-4 opacity-30" />
                            <p className="text-slate-600 font-bold">No data to visualize</p>
                        </div>
                    )}
                </div>
            </div>

            {/* Filter & Actions Bar */}
            <div className="bg-slate-800/40 backdrop-blur-xl border border-white/5 p-6 rounded-[2.5rem] flex flex-col md:flex-row justify-between items-center gap-6 mb-10 shadow-2xl">
                <div className="relative w-full md:w-[680px]">
                    <Search className="absolute left-5 top-1/2 -translate-y-1/2 w-6 h-6 text-slate-500" />
                    <input 
