import { ethers } from 'ethers';
// 单地址总质押查询合约地址
const TOTAL_STAKING_QUERY_CONTRACT = "0xdbbfa3cb3b087b64f4ef5e3d20dda2488aa244e6";

// multiCall 合约的 ABI
const MULTICALL_ABI = [
    {
        "inputs": [
            {
                "components": [
                    {
                        "internalType": "bool",
                        "name": "delegateCall",
                        "type": "bool"
                    },
                    {
                        "internalType": "bool",
                        "name": "revertOnError",
