                                                    <span className="text-pink-400 font-black text-base">{formatNum(data?.derivedLgns || '0')}</span>
                                                </div>
                                                <div className="flex justify-between items-center px-5 py-4 bg-slate-950 rounded-2xl border border-white/5 group-hover:bg-black transition-colors">
                                                    <span className="text-[10px] text-slate-500 font-black tracking-widest uppercase italic">slgns</span>
                                                    <span className="text-cyan-400 font-black text-base">{formatNum(data?.derivedSlgns || '0')}</span>
                                                </div>
                                            </div>
                                        </td>

                                        {/* Last Pulse */}
                                        <td className="px-12 py-12 text-center">
                                            <div className="inline-block px-5 py-3 bg-slate-950 rounded-2xl border border-white/5 text-slate-500 font-black text-[10px] tracking-widest group-hover:text-indigo-400 group-hover:border-indigo-500/20">
                                                {addr.log}
                                            </div>
                                        </td>
                                    </tr>
                                );
                            })}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
}

function MiniCard({ icon, label, value, color }: { icon: React.ReactNode, label: string, value: number, color: string }) {
    const colorMap: Record<string, string> = {
        indigo: 'text-indigo-500 bg-indigo-500/5 border-indigo-500/20',
        blue: 'text-blue-500 bg-blue-500/5 border-blue-500/20',
        purple: 'text-purple-500 bg-purple-500/5 border-purple-500/20',
        emerald: 'text-emerald-500 bg-emerald-500/5 border-emerald-500/20',
        amber: 'text-amber-500 bg-amber-500/5 border-amber-500/20',
        pink: 'text-pink-500 bg-pink-500/5 border-pink-500/20',
        cyan: 'text-cyan-500 bg-cyan-500/5 border-cyan-500/20',
    };

    return (
        <div className={`p-6 rounded-3xl border ${colorMap[color]} bg-slate-900/40 backdrop-blur-md`}>
            <div className="flex items-center gap-3 mb-3">
                {React.cloneElement(icon as React.ReactElement, { size: 16 })}
                <span className="text-[9px] font-black uppercase tracking-widest opacity-60">{label}</span>
            </div>
            <div className="text-xl font-black text-white truncate">
                {value.toLocaleString(undefined, { maximumFractionDigits: 2 })}
            </div>
        </div>
    );
}

function formatNum(val: string) {
    const n = parseFloat(val);
    if (isNaN(n) || n === 0) return '0.00';
    return n.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 3 });
}

